{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.cut_size_analysis as ( WITH final_first_live_date AS ( select sku_group sku_group, status, live_date as live_date_final, price, category, sku_class from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by status desc) = 1 ), inventory AS ( SELECT upper(trim(\"Item SkuCode\")) AS sku, upper(trim(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), CHARINDEX(\'-\', REVERSE(\"Item SkuCode\")) + 1, LEN(\"Item SkuCode\"))))) AS sku_group, date, SUM(inventory) AS total_inventory FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility in (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\') GROUP BY upper(trim(\"Item SkuCode\")), upper(trim(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), CHARINDEX(\'-\', REVERSE(\"Item SkuCode\")) + 1, LEN(\"Item SkuCode\"))))), date ), price as ( select distinct sku_group, original_price as price from snitch_db.maplemonk.product_journey ), cost_price as ( select upper(trim(sku)) as sku, cost_price from snitch_db.maplemonk.sku_cost_price qualify row_number() over (partition by sku order by cost_price desc) = 1 ), Final_inventory_calculation as ( SELECT case when b.category in (\'Perfumes\',\'Accessories\',\'Sunglasses\',\'Bags\') then \'1\' else SPLIT_PART(a.sku, \'-\', -1) end AS size, a.sku, a.sku_group, a.total_inventory, a.date, b.live_date_final, b.category, b.sku_class, CASE WHEN b.live_date_final >= DATEADD(day, -60, CURRENT_DATE) THEN \'New\' ELSE b.sku_class END AS class FROM inventory a LEFT JOIN final_first_live_date b ON a.sku_group = b.sku_group GROUP BY case when b.category in (\'Perfumes\',\'Accessories\',\'Sunglasses\',\'Bags\') then \'1\' else SPLIT_PART(a.sku, \'-\', -1) end, a.sku, a.sku_group, a.total_inventory, b.live_date_final, b.category, b.sku_class, a.date ), total_size as ( select sku_group, date, count(sku_group) as total_size, count(case when total_inventory = 0 and size in (\'S\',\'M\',\'L\',\'XL\',\'30\',\'32\',\'34\',\'36\') then sku_group end) as cut_sizes, count(case when total_inventory = 0 then sku_group end) as final_cut_sizes, count(case when total_inventory >= 5 then sku_group end) as sizes_above_5, count(case when total_inventory >= 10 then sku_group end) as sizes_above_10, count(case when total_inventory >= 40 then sku_group end) as sizes_above_40, count(case when total_inventory < 5 and size in (\'S\',\'M\',\'L\',\'XL\',\'30\',\'32\',\'34\',\'36\') then sku_group end) as cut_sizes_below_5, count(case when total_inventory < 10 and size in (\'S\',\'M\',\'L\',\'XL\',\'30\',\'32\',\'34\',\'36\') then sku_group end) as cut_sizes_below_10 from Final_inventory_calculation group by 1,2 ), final_check as ( select a.*,b.total_size,b.cut_sizes,b.cut_sizes_below_10,b.final_cut_sizes,b.cut_sizes_below_5,b.sizes_above_5,b.sizes_above_10,b.sizes_above_40,c.price,d.cost_price from Final_inventory_calculation a left join total_size b on a.sku_group = b.sku_group and a.date = b.date LEFT JOIN PRICE C ON a.sku_group = c.sku_group left join cost_price d on a.sku = d.sku where sku_class != \'4-New-Not-Sold\' ), inv_check as ( select date, sku_group, \'no_inv\' as type, sum(total_inventory) as inv from final_check group by 1,2,3 having sum(total_inventory) = 0 ), style as ( select sku_group, style from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by status desc) = 1 ) select a.*, coalesce(b.type,\'inv\') as inv_filter, c.style from final_check a left join inv_check b on a.sku_group = b.sku_group and a.date = b.date left join style c on a.sku_group = c.sku_group );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            